-- Dokument AI project management and construction operations foundation.
-- Review and apply with `supabase db push`. Business records use soft delete; no destructive project cascades.
create type public.project_role as enum ('project_owner','project_manager','site_manager','foreman','engineer','supervisor','accountant','procurement','subcontractor_manager','worker','viewer');

alter table public.projects add column if not exists company_id uuid references public.companies(id) on delete set null, add column if not exists project_code text not null default '', add column if not exists description text not null default '', add column if not exists project_type text not null default 'other', add column if not exists priority text not null default 'normal', add column if not exists address text not null default '', add column if not exists city text not null default '', add column if not exists postal_code text not null default '', add column if not exists country text not null default '', add column if not exists latitude numeric(10,7), add column if not exists longitude numeric(10,7), add column if not exists start_date date, add column if not exists expected_end_date date, add column if not exists actual_end_date date, add column if not exists contract_value numeric(18,2) not null default 0, add column if not exists budget numeric(18,2) not null default 0, add column if not exists progress_percent numeric(5,2) not null default 0, add column if not exists health_status text not null default 'on_track', add column if not exists risk_level text not null default 'normal', add column if not exists project_manager_user_id uuid references auth.users(id) on delete set null, add column if not exists site_manager_user_id uuid references auth.users(id) on delete set null, add column if not exists foreman_user_id uuid references auth.users(id) on delete set null, add column if not exists cover_image_path text, add column if not exists archived_at timestamptz;
alter table public.project_members add column if not exists expires_at timestamptz, add column if not exists module_permissions text[] not null default '{}', add column if not exists location_ids uuid[] not null default '{}', add column if not exists read_only boolean not null default false, add column if not exists deleted_at timestamptz;
alter table public.project_phases add column if not exists parent_phase_id uuid references public.project_phases(id) on delete set null, add column if not exists code text not null default '', add column if not exists description text not null default '', add column if not exists progress_percent numeric(5,2) not null default 0, add column if not exists planned_start date, add column if not exists planned_end date, add column if not exists actual_start date, add column if not exists actual_end date, add column if not exists budget numeric(18,2) not null default 0, add column if not exists cost numeric(18,2) not null default 0, add column if not exists responsible_user_id uuid references auth.users(id) on delete set null, add column if not exists responsible_company_id uuid references public.companies(id) on delete set null, add column if not exists color_key text, add column if not exists is_visible boolean not null default true, add column if not exists updated_at timestamptz not null default now();
alter table public.project_locations rename column parent_id to parent_location_id;
alter table public.project_locations add column if not exists code text not null default '', add column if not exists description text not null default '', add column if not exists active boolean not null default true, add column if not exists updated_at timestamptz not null default now();

create or replace function public.is_project_member(pid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.project_members pm where pm.project_id=pid and pm.user_id=(select auth.uid()) and pm.deleted_at is null and (pm.expires_at is null or pm.expires_at>now())) or exists(select 1 from public.projects p where p.id=pid and public.is_org_member(p.organization_id)) $$;
create or replace function public.has_project_roles(pid uuid, roles public.project_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.project_members pm where pm.project_id=pid and pm.user_id=(select auth.uid()) and pm.deleted_at is null and (pm.expires_at is null or pm.expires_at>now()) and pm.role::text=any(roles::text[])) or exists(select 1 from public.projects p where p.id=pid and public.has_org_role(p.organization_id,array['owner','admin']::public.organization_role[])) $$;
revoke all on function public.is_project_member(uuid),public.has_project_roles(uuid,public.project_role[]) from public; grant execute on function public.is_project_member(uuid),public.has_project_roles(uuid,public.project_role[]) to authenticated;

