create table public.project_checklists (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), project_id uuid not null references public.projects(id), template_id uuid references public.checklist_templates(id) on delete set null, name text not null, category text, responsible_user_id uuid references auth.users(id) on delete set null, due_date date, status text not null default 'open', signature_path text, note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, deleted_at timestamptz);
create table public.project_templates (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, definition jsonb not null, is_default boolean not null default false, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, deleted_at timestamptz);
create table public.project_activity_feed (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), project_id uuid not null references public.projects(id), actor_user_id uuid references auth.users(id) on delete set null, activity_type text not null, entity_type text, entity_id uuid, safe_metadata jsonb not null default '{}', created_at timestamptz not null default now());

alter table public.documents add column if not exists project_phase_id uuid references public.project_phases(id) on delete set null, add column if not exists project_location_id uuid references public.project_locations(id) on delete set null;
create index project_tasks_project_status_due_idx on public.project_tasks(project_id,status,due_date) where deleted_at is null;
create index worker_time_project_date_idx on public.worker_time_entries(project_id,entry_date desc) where deleted_at is null;
create index materials_project_status_idx on public.project_materials(project_id,status) where deleted_at is null;
create index costs_project_date_idx on public.project_costs(project_id,cost_date desc) where deleted_at is null;
create index issues_project_status_due_idx on public.project_issues(project_id,status,due_date) where deleted_at is null;
create index photos_project_taken_idx on public.project_photos(project_id,taken_at desc) where deleted_at is null;
create index activity_project_created_idx on public.project_activity_feed(project_id,created_at desc);

do $$ declare t text; begin foreach t in array array['project_tasks','task_assignees','task_dependencies','task_comments','task_checklist_items','task_time_entries','worker_project_assignments','worker_time_entries','project_materials','material_requests','material_request_items','material_deliveries','material_delivery_items','project_storage_locations','material_stock_movements','equipment_project_assignments','equipment_usage','project_costs','project_budgets','budget_lines','project_issues','project_risks','project_meetings','meeting_items','project_photos','project_milestones','project_calendar_events','project_checklists','project_activity_feed'] loop execute format('alter table public.%I enable row level security',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('create policy %I_project_read on public.%I for select to authenticated using(public.is_project_member(project_id))',t,t); execute format('create policy %I_project_write on public.%I for all to authenticated using(public.has_project_roles(project_id,array[''project_owner'',''project_manager'',''site_manager'',''foreman'',''engineer'',''supervisor'',''accountant'',''procurement'',''subcontractor_manager'']::public.project_role[])) with check(public.has_project_roles(project_id,array[''project_owner'',''project_manager'',''site_manager'',''foreman'',''engineer'',''supervisor'',''accountant'',''procurement'',''subcontractor_manager'']::public.project_role[]))',t,t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['workers','work_crews','crew_members','worker_skills','worker_certifications','equipment','equipment_maintenance','cost_categories','checklist_templates','project_templates'] loop execute format('alter table public.%I enable row level security',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('create policy %I_org_read on public.%I for select to authenticated using(public.is_org_member(organization_id))',t,t); execute format('create policy %I_org_write on public.%I for all to authenticated using(public.has_org_role(organization_id,array[''owner'',''admin'',''manager'',''editor'']::public.organization_role[])) with check(public.has_org_role(organization_id,array[''owner'',''admin'',''manager'',''editor'']::public.organization_role[]))',t,t); end loop; end $$;
alter table public.approval_requests enable row level security; alter table public.approval_steps enable row level security; grant select,insert,update,delete on public.approval_requests,public.approval_steps to authenticated;
create policy approvals_read on public.approval_requests for select to authenticated using((project_id is not null and public.is_project_member(project_id)) or public.is_org_member(organization_id));
create policy approvals_write on public.approval_requests for all to authenticated using((project_id is not null and public.has_project_roles(project_id,array['project_owner','project_manager','site_manager','supervisor','accountant','procurement']::public.project_role[])) or public.has_org_role(organization_id,array['owner','admin','manager']::public.organization_role[])) with check(public.is_org_member(organization_id));
create policy approval_steps_read on public.approval_steps for select to authenticated using((project_id is not null and public.is_project_member(project_id)) or public.is_org_member(organization_id));
create policy approval_steps_write on public.approval_steps for all to authenticated using(approver_user_id=(select auth.uid()) or (project_id is not null and public.has_project_roles(project_id,array['project_owner','project_manager']::public.project_role[]))) with check(public.is_org_member(organization_id));

-- Private project media lives under private-documents/{organization_id}/projects/{project_id}/...
-- Existing storage bucket policies enforce organization membership; signed URLs remain server-generated and short lived.
